from typing import List, Any

class Stack:
    """LIFO stack implemented on top of a Python list.

    Examples:
        >>> s = Stack()
        >>> s.push(1); s.push(2)
        >>> s.pop()
        2
        >>> s.peek()
        1
        >>> s.is_empty()
        False
    """
    def __init__(self) -> None:
        self._data: List[Any] = []

    def push(self, value: Any) -> None:
        self._data.append(value)

    def pop(self) -> Any:
        if not self._data:
            raise IndexError("pop from empty stack")
        return self._data.pop()

    def peek(self) -> Any:
        if not self._data:
            raise IndexError("peek from empty stack")
        return self._data[-1]

    def is_empty(self) -> bool:
        return not self._data

    def __len__(self) -> int:
        return len(self._data)

if __name__ == "__main__":
    s = Stack()
    for v in [10, 20, 30]:
        s.push(v)
    while not s.is_empty():
        print(s.pop())

from typing import List, Any

class BoundedStack:
    """Stack with a maximum capacity.

    Examples:
        >>> s = BoundedStack(2)
        >>> s.push(1); s.push(2)
        >>> s.push(3)
        Traceback (most recent call last):
            ...
        OverflowError: stack full
    """
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self._data: List[Any] = []

    def push(self, value: Any) -> None:
        if len(self._data) >= self.capacity:
            raise OverflowError("stack full")
        self._data.append(value)

    def pop(self) -> Any:
        if not self._data:
            raise IndexError("stack empty")
        return self._data.pop()

    def __len__(self) -> int:
        return len(self._data)

if __name__ == "__main__":
    s = BoundedStack(3)
    s.push("x"); s.push("y")
    print(len(s), s.pop())

from typing import List, Optional

class MinStack:
    """Stack that supports O(1) minimum retrieval.

    Examples:
        >>> s = MinStack()
        >>> s.push(3); s.push(1); s.push(2)
        >>> s.get_min()
        1
        >>> s.pop()
        2
        >>> s.get_min()
        1
    """
    def __init__(self) -> None:
        self.stack: List[int] = []
        self.mins: List[int] = []

    def push(self, value: int) -> None:
        self.stack.append(value)
        if not self.mins or value <= self.mins[-1]:
            self.mins.append(value)

    def pop(self) -> int:
        if not self.stack:
            raise IndexError("pop from empty stack")
        v = self.stack.pop()
        if v == self.mins[-1]:
            self.mins.pop()
        return v

    def top(self) -> Optional[int]:
        return self.stack[-1] if self.stack else None

    def get_min(self) -> Optional[int]:
        return self.mins[-1] if self.mins else None

if __name__ == "__main__":
    s = MinStack()
    for v in [5, 2, 4, 1, 3]:
        s.push(v)
    print(s.get_min(), s.pop(), s.get_min())

from typing import Deque, Any
from collections import deque

class Queue:
    """FIFO queue built on collections.deque.

    Examples:
        >>> q = Queue()
        >>> q.enqueue(1); q.enqueue(2)
        >>> q.dequeue()
        1
        >>> q.peek()
        2
    """
    def __init__(self) -> None:
        self._data: Deque[Any] = deque()

    def enqueue(self, value: Any) -> None:
        self._data.append(value)

    def dequeue(self) -> Any:
        if not self._data:
            raise IndexError("dequeue from empty queue")
        return self._data.popleft()

    def peek(self) -> Any:
        if not self._data:
            raise IndexError("peek from empty queue")
        return self._data[0]

    def __len__(self) -> int:
        return len(self._data)

if __name__ == "__main__":
    q = Queue()
    q.enqueue("a"); q.enqueue("b")
    while len(q) > 0:
        print(q.dequeue())

from typing import Deque, Any
from collections import deque

class DequeStack:
    """A stack/queue hybrid that supports both push/pop and appendleft/popleft."""
    def __init__(self) -> None:
        self.items: Deque[Any] = deque()

    def push_back(self, value: Any) -> None:
        """Push to the right end."""
        self.items.append(value)

    def push_front(self, value: Any) -> None:
        """Push to the left end."""
        self.items.appendleft(value)

    def pop_back(self) -> Any:
        """Pop from the right end."""
        return self.items.pop()

    def pop_front(self) -> Any:
        """Pop from the left end."""
        return self.items.popleft()

if __name__ == "__main__":
    d = DequeStack()
    d.push_back(1); d.push_back(2); d.push_front(0)
    print(d.pop_front(), d.pop_back())

from typing import List, Any

class CircularBuffer:
    """A circular buffer that overwrites the oldest entry when full.

    Examples:
        >>> b = CircularBuffer(3)
        >>> for v in [1, 2, 3, 4, 5]: b.write(v)
        >>> b.read_all()
        [3, 4, 5]
    """
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self._buf: List[Any] = [None] * capacity
        self.head = 0
        self.count = 0

    def write(self, value: Any) -> None:
        idx = (self.head + self.count) % self.capacity
        self._buf[idx] = value
        if self.count < self.capacity:
            self.count += 1
        else:
            self.head = (self.head + 1) % self.capacity

    def read_all(self) -> List[Any]:
        return [self._buf[(self.head + i) % self.capacity] for i in range(self.count)]

if __name__ == "__main__":
    b = CircularBuffer(4)
    for v in [1, 2, 3, 4, 5, 6]:
        b.write(v)
    print(b.read_all())

from typing import List, Any

class MinHeap:
    """Binary min-heap on top of a Python list.

    Examples:
        >>> h = MinHeap()
        >>> for v in [5, 3, 7, 1]: h.push(v)
        >>> h.peek()
        1
        >>> h.pop()
        1
        >>> h.peek()
        3
    """
    def __init__(self) -> None:
        self._data: List[Any] = []

    def __len__(self) -> int:
        return len(self._data)

    def peek(self) -> Any:
        if not self._data:
            raise IndexError("peek from empty heap")
        return self._data[0]

    def push(self, value: Any) -> None:
        self._data.append(value)
        self._sift_up(len(self._data) - 1)

    def pop(self) -> Any:
        if not self._data:
            raise IndexError("pop from empty heap")
        top = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._sift_down(0)
        return top

    def _sift_up(self, idx: int) -> None:
        while idx > 0:
            parent = (idx - 1) // 2
            if self._data[parent] <= self._data[idx]:
                break
            self._data[parent], self._data[idx] = self._data[idx], self._data[parent]
            idx = parent

    def _sift_down(self, idx: int) -> None:
        n = len(self._data)
        while True:
            smallest = idx
            left = 2 * idx + 1
            right = 2 * idx + 2
            if left < n and self._data[left] < self._data[smallest]:
                smallest = left
            if right < n and self._data[right] < self._data[smallest]:
                smallest = right
            if smallest == idx:
                break
            self._data[idx], self._data[smallest] = self._data[smallest], self._data[idx]
            idx = smallest

if __name__ == "__main__":
    h = MinHeap()
    for v in [9, 4, 1, 6, 7, 3]:
        h.push(v)
    out = []
    while len(h) > 0:
        out.append(h.pop())
    print(out)

from typing import List, Any

class MaxHeap:
    """Binary max-heap.

    Examples:
        >>> h = MaxHeap()
        >>> for v in [2, 7, 4]: h.push(v)
        >>> h.peek()
        7
    """
    def __init__(self) -> None:
        self._data: List[Any] = []

    def push(self, value: Any) -> None:
        self._data.append(value)
        i = len(self._data) - 1
        while i > 0:
            p = (i - 1) // 2
            if self._data[p] >= self._data[i]:
                break
            self._data[p], self._data[i] = self._data[i], self._data[p]
            i = p

    def peek(self) -> Any:
        return self._data[0]

    def __len__(self) -> int:
        return len(self._data)

if __name__ == "__main__":
    h = MaxHeap()
    for v in [1, 5, 3, 8, 2]:
        h.push(v)
    print(h.peek(), len(h))

from typing import Dict, Optional

class CompactTrie:
    """Trie stored as nested dicts (no dedicated node class)."""
    def __init__(self) -> None:
        self.root: Dict[str, object] = {"$end": False}

    def insert(self, word: str) -> None:
        """Add a word to the trie.

        Examples:
            >>> t = CompactTrie(); t.insert('hi'); t.search('hi')
            True
        """
        node = self.root
        for ch in word:
            child = node.get(ch)
            if not isinstance(child, dict):
                child = {"$end": False}
                node[ch] = child
            node = child
        node["$end"] = True

    def search(self, word: str) -> bool:
        """Check if a word is present.

        Examples:
            >>> t = CompactTrie(); t.insert('cat'); t.search('car')
            False
        """
        node = self._walk(word)
        return isinstance(node, dict) and node.get("$end", False) is True

    def starts_with(self, prefix: str) -> bool:
        return self._walk(prefix) is not None

    def _walk(self, s: str) -> Optional[Dict[str, object]]:
        node: Optional[Dict[str, object]] = self.root
        for ch in s:
            if not isinstance(node, dict):
                return None
            node = node.get(ch)
            if node is None:
                return None
        return node if isinstance(node, dict) else None

if __name__ == "__main__":
    t = CompactTrie()
    t.insert("python")
    print(t.search("python"), t.starts_with("py"))

from typing import Dict

def trie_count_words_with_prefix(root: Dict, prefix: str) -> int:
    """Count words under a prefix in a dict-style trie.

    Args:
        root: The trie root (dict with $end key).
        prefix: The prefix to search.

    Returns:
        The number of words with that prefix.

    Examples:
        See __main__.
    """
    node = root
    for ch in prefix:
        nxt = node.get(ch)
        if not isinstance(nxt, dict):
            return 0
        node = nxt
    return _count(node)

def _count(node: Dict) -> int:
    total = 1 if node.get("$end") else 0
    for k, v in node.items():
        if k != "$end" and isinstance(v, dict):
            total += _count(v)
    return total

if __name__ == "__main__":
    root = {"$end": False}
    for w in ["a", "an", "ant", "and"]:
        node = root
        for ch in w:
            if ch not in node:
                node[ch] = {"$end": False}
            node = node[ch]
        node["$end"] = True
    print(trie_count_words_with_prefix(root, "an"))

from typing import Optional, List, Any

class ListNode:
    """A singly-linked list node."""
    def __init__(self, value: Any, next: Optional['ListNode'] = None) -> None:
        self.value = value
        self.next = next

class SinglyLinkedList:
    """A singly-linked list with head/tail and basic ops.

    Examples:
        >>> sll = SinglyLinkedList()
        >>> sll.append(1); sll.append(2); sll.append(3)
        >>> sll.to_list()
        [1, 2, 3]
        >>> sll.head().value
        1
        >>> sll.tail().value
        3
    """
    def __init__(self) -> None:
        self._head: Optional[ListNode] = None
        self._tail: Optional[ListNode] = None
        self._size = 0

    def __len__(self) -> int:
        return self._size

    def append(self, value: Any) -> None:
        node = ListNode(value)
        if self._tail is None:
            self._head = node
        else:
            self._tail.next = node
        self._tail = node
        self._size += 1

    def prepend(self, value: Any) -> None:
        node = ListNode(value, self._head)
        self._head = node
        if self._tail is None:
            self._tail = node
        self._size += 1

    def head(self) -> Optional[ListNode]:
        return self._head

    def tail(self) -> Optional[ListNode]:
        return self._tail

    def to_list(self) -> List[Any]:
        out: List[Any] = []
        cur = self._head
        while cur is not None:
            out.append(cur.value)
            cur = cur.next
        return out

    def find(self, value: Any) -> Optional[ListNode]:
        cur = self._head
        while cur is not None:
            if cur.value == value:
                return cur
            cur = cur.next
        return None

if __name__ == "__main__":
    sll = SinglyLinkedList()
    for v in [10, 20, 30]:
        sll.append(v)
    print(sll.to_list())

from typing import Optional, List, Any

class BSTNode:
    """A node for a Binary Search Tree."""
    def __init__(self, value: Any) -> None:
        self.value = value
        self.left: Optional['BSTNode'] = None
        self.right: Optional['BSTNode'] = None

class BinarySearchTree:
    """A binary search tree for comparable keys.

    Examples:
        >>> bst = BinarySearchTree()
        >>> for v in [5, 3, 7, 1, 4]: bst.insert(v)
        >>> bst.search(4)
        True
        >>> bst.search(99)
        False
    """
    def __init__(self) -> None:
        self.root: Optional[BSTNode] = None

    def insert(self, value: Any) -> None:
        if self.root is None:
            self.root = BSTNode(value)
            return
        cur = self.root
        while True:
            if value < cur.value:
                if cur.left is None:
                    cur.left = BSTNode(value)
                    return
                cur = cur.left
            elif value > cur.value:
                if cur.right is None:
                    cur.right = BSTNode(value)
                    return
                cur = cur.right
            else:
                return

    def search(self, value: Any) -> bool:
        cur = self.root
        while cur is not None:
            if value == cur.value:
                return True
            if value < cur.value:
                cur = cur.left
            else:
                cur = cur.right
        return False

    def inorder(self) -> List[Any]:
        """Return values via inorder traversal.

        Examples:
            >>> bst = BinarySearchTree()
            >>> for v in [3, 1, 2]: bst.insert(v)
            >>> bst.inorder()
            [1, 2, 3]
        """
        out: List[Any] = []
        self._inorder(self.root, out)
        return out

    def _inorder(self, node: Optional[BSTNode], out: List[Any]) -> None:
        if node is None:
            return
        self._inorder(node.left, out)
        out.append(node.value)
        self._inorder(node.right, out)

if __name__ == "__main__":
    bst = BinarySearchTree()
    for v in [10, 5, 15, 3, 7, 12, 20]:
        bst.insert(v)
    print(bst.inorder())
    print(bst.search(7), bst.search(99))

from typing import List, Any

class RingBuffer:
    """A fixed-capacity ring buffer that supports overwrite.

    Examples:
        >>> rb = RingBuffer(3)
        >>> for v in [1, 2, 3, 4, 5]: rb.push(v)
        >>> rb.to_list()
        [3, 4, 5]
    """
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self._buf: List[Any] = [None] * capacity
        self._head = 0
        self._size = 0

    def push(self, value: Any) -> None:
        idx = (self._head + self._size) % self.capacity
        self._buf[idx] = value
        if self._size < self.capacity:
            self._size += 1
        else:
            self._head = (self._head + 1) % self.capacity

    def pop_oldest(self) -> Any:
        if self._size == 0:
            raise IndexError("pop from empty ring")
        value = self._buf[self._head]
        self._head = (self._head + 1) % self.capacity
        self._size -= 1
        return value

    def to_list(self) -> List[Any]:
        return [self._buf[(self._head + i) % self.capacity] for i in range(self._size)]

    def __len__(self) -> int:
        return self._size

if __name__ == "__main__":
    rb = RingBuffer(4)
    for v in [10, 20, 30, 40, 50]:
        rb.push(v)
    print(rb.to_list())

from typing import Iterator, Any

class RingBufferIter:
    """A ring buffer that supports iteration in oldest-to-newest order.

    Examples:
        >>> rb = RingBufferIter(3)
        >>> for v in [1, 2, 3, 4]: rb.push(v)
        >>> list(rb)
        [2, 3, 4]
    """
    def __init__(self, capacity: int) -> None:
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self._buf: list = []

    def push(self, value: Any) -> None:
        self._buf.append(value)
        if len(self._buf) > self.capacity:
            self._buf.pop(0)

    def __iter__(self) -> Iterator[Any]:
        return iter(self._buf)

if __name__ == "__main__":
    rb = RingBufferIter(4)
    for v in [1, 2, 3, 4, 5, 6]:
        rb.push(v)
    print(list(rb))

from typing import Callable, Dict, List, Any

class EventEmitter:
    """A minimal synchronous event emitter.

    Examples:
        >>> e = EventEmitter()
        >>> seen = []
        >>> e.on('tick', seen.append)
        >>> e.emit('tick', 1); e.emit('tick', 2)
        >>> seen
        [1, 2]
    """
    def __init__(self) -> None:
        self._handlers: Dict[str, List[Callable[..., None]]] = {}

    def on(self, event: str, handler: Callable[..., None]) -> None:
        self._handlers.setdefault(event, []).append(handler)

    def off(self, event: str, handler: Callable[..., None]) -> None:
        lst = self._handlers.get(event, [])
        if handler in lst:
            lst.remove(handler)

    def emit(self, event: str, *args: Any) -> None:
        for handler in list(self._handlers.get(event, [])):
            handler(*args)

    def listener_count(self, event: str) -> int:
        """Return the number of listeners for the given event.

        Examples:
            >>> EventEmitter().listener_count('x')
            0
        """
        return len(self._handlers.get(event, []))

if __name__ == "__main__":
    em = EventEmitter()
    out: List[int] = []
    em.on("ping", lambda v: out.append(v))
    em.emit("ping", 42)
    print(out)

from typing import Callable, Any

class OnceEmitter:
    """Emitter where a handler fires only on its first event.

    Examples:
        >>> e = OnceEmitter()
        >>> log = []
        >>> e.once('ready', lambda: log.append('go'))
        >>> e.emit('ready'); e.emit('ready')
        >>> log
        ['go']
    """
    def __init__(self) -> None:
        self._handlers: dict = {}

    def once(self, event: str, handler: Callable[..., None]) -> None:
        """Register a one-shot handler."""
        def wrapper(*args: Any) -> None:
            handler(*args)
            self.off(event, wrapper)
        self.on(event, wrapper)

    def on(self, event: str, handler: Callable[..., None]) -> None:
        self._handlers.setdefault(event, []).append(handler)

    def off(self, event: str, handler: Callable[..., None]) -> None:
        lst = self._handlers.get(event, [])
        if handler in lst:
            lst.remove(handler)

    def emit(self, event: str, *args: Any) -> None:
        for h in list(self._handlers.get(event, [])):
            h(*args)

if __name__ == "__main__":
    em = OnceEmitter()
    log = []
    em.once("ready", lambda: log.append("fired"))
    em.emit("ready")
    em.emit("ready")
    print(log)

from typing import Any, Dict

class BiCounter:
    """Counter with explicit increment/decrement operations.

    Examples:
        >>> b = BiCounter()
        >>> b.inc('a'); b.inc('a'); b.dec('a')
        >>> b.get('a')
        1
    """
    def __init__(self) -> None:
        self._c: Dict[Any, int] = {}

    def inc(self, key: Any, by: int = 1) -> int:
        self._c[key] = self._c.get(key, 0) + by
        return self._c[key]

    def dec(self, key: Any, by: int = 1) -> int:
        self._c[key] = self._c.get(key, 0) - by
        return self._c[key]

    def get(self, key: Any) -> int:
        return self._c.get(key, 0)

    def keys(self):
        return self._c.keys()

if __name__ == "__main__":
    b = BiCounter()
    b.inc("x"); b.inc("y", 2); b.dec("y")
    print({k: b.get(k) for k in b.keys()})

from typing import Any, Optional, Iterator, Tuple

class LRUIter:
    """An LRU cache that supports iteration in MRU-to-LRU order."""
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.store: dict = {}
        self.order: list = []

    def put(self, key: Any, value: Any) -> None:
        if key in self.store:
            self.order.remove(key)
        self.store[key] = value
        self.order.append(key)
        while len(self.order) > self.capacity:
            ev = self.order.pop(0)
            self.store.pop(ev, None)

    def get(self, key: Any) -> Optional[Any]:
        if key not in self.store:
            return None
        self.order.remove(key); self.order.append(key)
        return self.store[key]

    def __iter__(self) -> Iterator[Tuple[Any, Any]]:
        """Iterate (key, value) from most- to least-recently used."""
        for k in reversed(self.order):
            yield k, self.store[k]

if __name__ == "__main__":
    c = LRUIter(3)
    c.put("a", 1); c.put("b", 2); c.put("c", 3)
    print(list(c))

from typing import List, Any

class TwoStackQueue:
    """A queue implemented with two stacks (amortized O(1)).

    Examples:
        >>> q = TwoStackQueue()
        >>> q.enqueue(1); q.enqueue(2)
        >>> q.dequeue()
        1
        >>> q.peek()
        2
    """
    def __init__(self) -> None:
        self.in_stack: List[Any] = []
        self.out_stack: List[Any] = []

    def _move(self) -> None:
        if not self.out_stack:
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())

    def enqueue(self, value: Any) -> None:
        self.in_stack.append(value)

    def dequeue(self) -> Any:
        self._move()
        if not self.out_stack:
            raise IndexError("dequeue from empty queue")
        return self.out_stack.pop()

    def peek(self) -> Any:
        self._move()
        if not self.out_stack:
            raise IndexError("peek from empty queue")
        return self.out_stack[-1]

if __name__ == "__main__":
    q = TwoStackQueue()
    for v in [1, 2, 3]:
        q.enqueue(v)
    print(q.dequeue(), q.dequeue())

