class PriorityQueue:
    """Min-heap-backed priority queue."""
    def __init__(self) -> None:
        self._data: List[Any] = []

    def push(self, priority: int, value: Any) -> None:
        self._data.append((priority, value))
        self._sift_up(len(self._data) - 1)

    def pop(self) -> Any:
        if not self._data:
            raise IndexError("empty pq")
        return self._data.pop(0)[1] if len(self._data) == 1 else self._pop_root()[1]

    def peek(self) -> Any:
        return self._data[0][1]

    def _pop_root(self) -> Any:
        top = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._sift_down(0)
        return top

    def _sift_up(self, i: int) -> None:
        while i > 0:
            p = (i - 1) // 2
            if self._data[p][0] <= self._data[i][0]:
                break
            self._data[p], self._data[i] = self._data[i], self._data[p]
            i = p

    def _sift_down(self, i: int) -> None:
        n = len(self._data)
        while True:
            s = i
            l = 2 * i + 1
            r = 2 * i + 2
            if l < n and self._data[l][0] < self._data[s][0]:
                s = l
            if r < n and self._data[r][0] < self._data[s][0]:
                s = r
            if s == i:
                break
            self._data[i], self._data[s] = self._data[s], self._data[i]
            i = s

