def interval_normalize(intervals: List[tuple]) -> List[tuple]:
    """Sort intervals and clamp each end to be at least the start."""
    out = []
    for s, e in sorted(intervals, key=lambda iv: iv[0]):
        if e < s:
            e = s
        out.append((s, e))
    return out

