class EventEmitter3:
    """A third EventEmitter with subscribe_alias()."""
    def __init__(self) -> None:
        self._handlers: dict = {}

    def subscribe_alias(self, event: str, alias: str) -> None:
        """Map alias to event so that subscribers see both names."""
        self._handlers.setdefault(event, [])
        self._handlers.setdefault(alias, []).extend(self._handlers[event])

    def on(self, event: str, handler: Any) -> None:
        self._handlers.setdefault(event, []).append(handler)

    def emit(self, event: str, *args: Any) -> None:
        for h in list(self._handlers.get(event, [])):
            h(*args)

